INSERT INTO questionnaires (name, service_id, version_type, status, created_by, total_criteria, published_at)
SELECT 'Evaluacion atención prehospitalaria (Res. 3100/2019)', s.id, 'initial', 'published',
  (SELECT id FROM users WHERE email = 'admin@prueba.com' LIMIT 1),
  (SELECT COUNT(*) FROM evaluation_criteria ec WHERE ec.service_id = s.id), NOW()
FROM services s WHERE s.code = 'APH'
ON CONFLICT DO NOTHING;

INSERT INTO questionnaire_criteria (questionnaire_id, criterion_id)
SELECT q.id, ec.id
FROM questionnaires q
JOIN services s ON s.id = q.service_id
JOIN evaluation_criteria ec ON ec.service_id = s.id
WHERE s.code = 'APH' AND q.version_type = 'initial'
ON CONFLICT DO NOTHING;

