SELECT 'APR-INT-020', '35.2', '35.2. Servicio de cuidado intensivo adultos.', '35.2. Servicio de cuidado intensivo adultos.',
  es.id, s.id, true, 'active'
FROM evaluation_standards es JOIN services s ON s.id = es.service_id
WHERE es.code = 'APR_INT' AND s.code = 'APR'
ON CONFLICT (code, service_id) DO NOTHING;
INSERT INTO evaluation_criteria (code, number, name, description, standard_id, service_id, is_mandatory, status)
SELECT 'APR-INT-021', '36', '36. No aplica.', '36. No aplica.',
  es.id, s.id, true, 'active'
FROM evaluation_standards es JOIN services s ON s.id = es.service_id
WHERE es.code = 'APR_INT' AND s.code = 'APR'
ON CONFLICT (code, service_id) DO NOTHING;

INSERT INTO questionnaires (name, service_id, version_type, status, created_by, total_criteria, published_at)
SELECT 'Evaluacion para la atención del parto (Res. 3100/2019)', s.id, 'initial', 'published',
  (SELECT id FROM users WHERE email = 'admin@prueba.com' LIMIT 1),
  (SELECT COUNT(*) FROM evaluation_criteria ec WHERE ec.service_id = s.id), NOW()
FROM services s WHERE s.code = 'APR'
ON CONFLICT DO NOTHING;

INSERT INTO questionnaire_criteria (questionnaire_id, criterion_id)
SELECT q.id, ec.id
FROM questionnaires q
JOIN services s ON s.id = q.service_id
JOIN evaluation_criteria ec ON ec.service_id = s.id
WHERE s.code = 'APR' AND q.version_type = 'initial'
ON CONFLICT DO NOTHING;

